// Convert binary input file or JSON body to Base64 format for Vision API
const item = $input.first();
let base64Data = '';
let mimeType = 'image/jpeg';
let fileName = 'invoice.jpg';

if (item.binary && item.binary.data) {
  base64Data = item.binary.data.data;
  mimeType = item.binary.data.mimeType || 'image/jpeg';
  fileName = item.binary.data.fileName || 'invoice.jpg';
} else if (item.json && item.json.file_base64) {
  base64Data = item.json.file_base64.replace(/^data:[^;]+;base64,/, '');
  mimeType = item.json.file_type || 'image/jpeg';
  fileName = item.json.file_name || 'invoice.jpg';
} else if (item.json && item.json.body && item.json.body.file_base64) {
  base64Data = item.json.body.file_base64.replace(/^data:[^;]+;base64,/, '');
  mimeType = item.json.body.file_type || 'image/jpeg';
  fileName = item.json.body.file_name || 'invoice.jpg';
}

// Ensure Vision API URL accepts valid image mime scheme
let imageMimeType = (mimeType && mimeType.startsWith('image/')) ? mimeType : 'image/jpeg';

return [{
  json: {
    fileName,
    mimeType,
    imageMimeType,
    base64Data
  }
}];

