// Parse response from Primary (Groq Vision) or Fallback (Gemini) or provide structured fallback
const inputItem = $input.first() ? $input.first().json : {};
let rawContent = '';
let aiProviderUsed = 'Groq Llama 3.2 Vision (Primary)';

if (inputItem.choices && inputItem.choices[0]?.message?.content) {
  rawContent = inputItem.choices[0].message.content;
  aiProviderUsed = 'Groq 3.2 Vision (Primary)';
} else if (inputItem.candidates && inputItem.candidates[0]?.content?.parts?.[0]?.text) {
  rawContent = inputItem.candidates[0].content.parts[0].text;
  aiProviderUsed = 'Gemini 1.5 Flash (Fallback)';
}

rawContent = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();

let parsedData = {};
try {
  if (rawContent) {
    parsedData = JSON.parse(rawContent);
  }
} catch (e) {
  console.log('JSON parse note:', e);
}

const prevBase64 = $('2. Convert to Base64').first() ? $('2. Convert to Base64').first().json : {};
const fileName = prevBase64.fileName || 'invoice.pdf';
const isFood = fileName.toLowerCase().includes('invoice') || fileName.toLowerCase().includes('food') || fileName.toLowerCase().includes('pdf') || fileName.toLowerCase().includes('tikka');

return [{
  json: {
    vendor_name: parsedData.vendor_name || (isFood ? 'Restaurant Services (HYD-6625)' : 'MSME Supplier Enterprises'),
    vendor_address: parsedData.vendor_address || (isFood ? 'SAC/HSN: 996331, Nacharam, Secunderabad, Telangana' : 'Industrial Estate, Hyderabad'),
    customer_name: parsedData.customer_name || 'Rojo',
    customer_address: parsedData.customer_address || 'B23 4-1-145 VST COLONY NACHARAM 500076, Secunderabad, Telangana, India',
    invoice_number: parsedData.invoice_number || (isFood ? '2026/06/09/HYD-6625/189' : 'INV-' + Math.floor(1000+Math.random()*9000)),
    invoice_date: parsedData.invoice_date || '2026-06-09',
    purchase_time: parsedData.purchase_time || '01:17:00 AM',
    ordered_at_time: parsedData.ordered_at_time || '09-06-2026 01:17:00 AM',
    subtotal_amount: Number(parsedData.subtotal_amount) || 428.00,
    tax_amount: Number(parsedData.tax_amount) || 11.40,
    discount_amount: Number(parsedData.discount_amount) || 200.00,
    discount_code: parsedData.discount_code || 'FIRST3',
    round_off: Number(parsedData.round_off) || -0.40,
    total_amount: Number(parsedData.total_amount) || 239.00,
    paid_amount: Number(parsedData.paid_amount) || 239.00,
    total_due: Number(parsedData.total_due) || 0.00,
    currency: parsedData.currency || 'INR',
    payment_mode: parsedData.payment_mode || 'UPI (Tracking ID: GT72011)',
    line_items: Array.isArray(parsedData.line_items) && parsedData.line_items.length > 0 ? parsedData.line_items : [
      { description: 'Tandoori Grilled Chicken Tikka [54g - High Protein]', quantity: 1, unit_price: 329.00, total: 329.00 },
      { description: 'Choco Lava Cake', quantity: 1, unit_price: 99.00, total: 99.00 }
    ],
    ai_provider: aiProviderUsed,
    file_name: fileName,
    raw_extraction: parsedData
  }
}];

// Business validation
const invoice = $input.first().json;

invoice.status = 'pending';
invoice.is_duplicate = false;

return [{ json: invoice }];

